 document.addEventListener('click',event=>{const button=event.target.closest('[data-support="pause_audio"],[data-support="resume_audio"],[data-support="send_audio"]');if(!button)return;event.preventDefault();event.stopImmediatePropagation();const action=button.dataset.support;if(action==='pause_audio'&&recorder?.state==='recording'){recorder.pause();recordPaused=true;recordPauseStarted=Date.now()}else if(action==='resume_audio'&&recorder?.state==='paused'){recorder.resume();recordPausedTotal+=Date.now()-recordPauseStarted;recordPauseStarted=0;recordPaused=false}else if(action==='send_audio')stopRecording('send');paintRecording()},true);
