 document.addEventListener('click',async event=>{const button=event.target.closest('[data-support-action]');if(!button||busy)return;event.preventDefault();event.stopImmediatePropagation();const action=button.dataset.supportAction;let payload={message_id:button.dataset.message};if(action==='edit_message'){const current=conversation?.messages?.find(m=>m.id===button.dataset.message);const body=prompt('Editar mensagem:',current?.body||'');if(body===null)return;payload.body=body}else if(action==='delete_message'){if(!confirm('Excluir esta mensagem? Ela continuará indicada como “Mensagem excluída”.'))return}else if(action==='report_message'){const reason=prompt('Por que você quer denunciar esta mensagem?','Conteúdo inadequado');if(reason===null)return;payload.reason=reason}else if(action==='resolve_report'){payload={report_id:button.dataset.report}}else return;for(const menu of document.querySelectorAll('.message-actions[open]'))menu.open=false;busy=true;button.disabled=true;try{await rpc(action,payload);if(action==='resolve_report'){threadID=null;conversation=null}if(action==='edit_message'||action==='delete_message')document.querySelector('[data-support-root]')?.removeAttribute('data-thread');busy=false;await load();if(action==='report_message'){document.querySelector('[data-support-feedback]')?.remove();document.querySelector('[data-support-root]')?.insertAdjacentHTML('afterbegin','<p class="notice support-feedback" data-support-feedback role="status">Denúncia enviada à moderação. A outra pessoa não será avisada.</p>');setTimeout(()=>document.querySelector('[data-support-feedback]')?.remove(),5000)}}catch(err){error=err.message;draw()}finally{busy=false}},true);
